#include <map>

std::map<KeyType, ValueType> myMap;

//Insertion
myMap[key] = value;

//Lookup
ValueType value = myMap[key]; //Returns default-constructed ValueType if key doesn't exist.
bool containsKey = myMap.count(key) > 0;

//Safe Lookup with .at(): throws exception if key doesn't exist
ValueType value = myMap.at(key);
