code_example:
#include <iostream>
#include <map>
#include <string>

int main() {
  std::map<std::string, int> word_count;
  word_count["Anna"] = 5;
  word_count["Bob"] = 10;
  word_count["Charlie"] = 2;

  //Check if a key exists before accessing to avoid exceptions
  if (word_count.count("Anna")) {
      std::cout << "Anna's word count: " << word_count.at("Anna") << std::endl;
  }
  else {
      std::cout << "Anna's word count not found." << std::endl;
  }
  //Example of safe access using .at() which throws an exception if the key doesn't exist
  try {
      std::cout << "David's word count: " << word_count.at("David") << std::endl;
  } catch (const std::out_of_range& oor) {
      std::cerr << "Exception caught: " << oor.what() << std::endl;
  }
  return 0;
}
